def calculate_input():
    try:
        input_entry1 = float(entry_1.get())
        input_entry2 = float(entry_2.get())
        if input_entry2 !=0:
            calc_gear = round(input_entry1 / input_entry2, 2) 
            canvas.itemconfig(result_text_id, text=f"Výstupný prevodový pomer: {calc_gear}")
        else:
            messagebox.showerror("Chyba", "Delenie nulou je nemožné")
        
    except ValueError:
        messagebox.showerror("Chyba", "Prosím, zadajte platné číselné hodnoty!")

